import{_ as n,a as o}from"./CpCVfE0I.js";import{e as f,A as s,c as r,b as t,B as d,o as l,_ as c}from"./BHLZ2mCK.js";import"./DJTwKRX7.js";const v={class:"ferpa-compliance"},u=f({__name:"ferpa",setup(p){return s({title:"FERPA Compliance - Classsemble",description:"Learn about Classsemble's FERPA compliance measures for protecting student education records and privacy rights.",ogTitle:"FERPA Compliance - Classsemble",ogDescription:"Comprehensive FERPA compliance information for US educational institutions using Classsemble."}),(g,a)=>{const i=n,e=o;return l(),r("div",v,[t(i),a[0]||(a[0]=d('<section class="bg-gradient-to-br from-coral to-coral/80 text-white py-20 px-4" data-v-57f065f9><div class="max-w-4xl mx-auto text-center" data-v-57f065f9><h1 class="text-5xl font-bold mb-6" data-v-57f065f9>FERPA Compliance</h1><p class="text-xl opacity-90" data-v-57f065f9> Family Educational Rights and Privacy Act compliance for US educational institutions </p><p class="text-sm opacity-75 mt-4" data-v-57f065f9> Last updated: November 18, 2025 </p></div></section><section class="py-20 px-4 bg-white" data-v-57f065f9><div class="max-w-4xl mx-auto prose prose-lg" data-v-57f065f9><h2 data-v-57f065f9>1. Introduction to FERPA</h2><p data-v-57f065f9> The Family Educational Rights and Privacy Act (FERPA) is a federal privacy law that protects the privacy of student education records. FERPA applies to all schools that receive funds under an applicable program of the U.S. Department of Education. </p><p data-v-57f065f9> As an educational technology provider serving schools and universities, Classsemble is committed to full compliance with FERPA requirements and protecting student educational records in accordance with federal law. </p><h2 data-v-57f065f9>2. Our FERPA Responsibilities</h2><h3 data-v-57f065f9>2.1 School Official Status</h3><p data-v-57f065f9> Classsemble operates as a &quot;school official&quot; under FERPA when: </p><ul data-v-57f065f9><li data-v-57f065f9>We perform an institutional service or function for which the school would otherwise use employees</li><li data-v-57f065f9>We are under the direct control of the educational institution regarding use and maintenance of education records</li><li data-v-57f065f9>We are subject to the same conditions governing the use and redisclosure of personally identifiable information</li><li data-v-57f065f9>We have a legitimate educational interest in the education records</li></ul><h3 data-v-57f065f9>2.2 Legitimate Educational Interest</h3><p data-v-57f065f9> Our legitimate educational interest includes: </p><ul data-v-57f065f9><li data-v-57f065f9>Facilitating course collaboration and communication</li><li data-v-57f065f9>Enabling meeting scheduling for educational purposes</li><li data-v-57f065f9>Supporting instructor-student and peer-to-peer academic interactions</li><li data-v-57f065f9>Providing analytics to improve educational outcomes</li><li data-v-57f065f9>Ensuring platform security and data protection</li></ul><h2 data-v-57f065f9>3. Student Education Records</h2><h3 data-v-57f065f9>3.1 What Constitutes Education Records</h3><p data-v-57f065f9> Under FERPA, education records include records that: </p><ul data-v-57f065f9><li data-v-57f065f9>Are directly related to a student</li><li data-v-57f065f9>Are maintained by an educational agency or institution</li><li data-v-57f065f9>Contain personally identifiable information</li></ul><h3 data-v-57f065f9>3.2 FERPA-Protected Information in Our Platform</h3><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>Student Identifiers:</strong> Names, student ID numbers, email addresses</li><li data-v-57f065f9><strong data-v-57f065f9>Course Enrollment:</strong> Course participation, enrollment status</li><li data-v-57f065f9><strong data-v-57f065f9>Academic Communications:</strong> Messages, discussions, meeting participation</li><li data-v-57f065f9><strong data-v-57f065f9>Engagement Data:</strong> Platform usage, participation analytics</li><li data-v-57f065f9><strong data-v-57f065f9>Collaborative Work:</strong> Group project participation, meeting attendance</li></ul><h3 data-v-57f065f9>3.3 Information NOT Covered by FERPA</h3><ul data-v-57f065f9><li data-v-57f065f9>Sole possession records kept by instructors for personal use</li><li data-v-57f065f9>Law enforcement records maintained separately</li><li data-v-57f065f9>Alumni records that don&#39;t relate to the person as a student</li><li data-v-57f065f9>Public directory information (if properly designated)</li></ul><h2 data-v-57f065f9>4. Access and Disclosure Controls</h2><h3 data-v-57f065f9>4.1 Permitted Disclosures Without Consent</h3><p data-v-57f065f9> We may disclose student education records without written consent only to: </p><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>School Officials:</strong> Institutional personnel with legitimate educational interest</li><li data-v-57f065f9><strong data-v-57f065f9>Other Schools:</strong> Where student seeks enrollment (with proper procedures)</li><li data-v-57f065f9><strong data-v-57f065f9>Authorized Representatives:</strong> For audit, evaluation, or compliance purposes</li><li data-v-57f065f9><strong data-v-57f065f9>Financial Aid Officials:</strong> For determining aid eligibility</li><li data-v-57f065f9><strong data-v-57f065f9>Organizations Conducting Studies:</strong> For educational agencies (with strict controls)</li><li data-v-57f065f9><strong data-v-57f065f9>Accrediting Organizations:</strong> For accreditation functions</li><li data-v-57f065f9><strong data-v-57f065f9>Legal Compliance:</strong> To comply with judicial order or subpoena</li><li data-v-57f065f9><strong data-v-57f065f9>Health/Safety Emergency:</strong> To protect health or safety</li></ul><h3 data-v-57f065f9>4.2 Written Consent Requirements</h3><p data-v-57f065f9> When written consent is required, it must specify: </p><ul data-v-57f065f9><li data-v-57f065f9>Records to be disclosed</li><li data-v-57f065f9>Purpose of the disclosure</li><li data-v-57f065f9>Party to whom disclosure may be made</li><li data-v-57f065f9>Student&#39;s signature and date</li></ul><h2 data-v-57f065f9>5. Student Rights Under FERPA</h2><h3 data-v-57f065f9>5.1 Right to Inspect and Review</h3><p data-v-57f065f9> Students have the right to: </p><ul data-v-57f065f9><li data-v-57f065f9>Inspect and review their education records within 45 days of request</li><li data-v-57f065f9>Receive copies of records (fees may apply)</li><li data-v-57f065f9>Have records explained or interpreted by school officials</li><li data-v-57f065f9>Receive a list of types and locations of education records</li></ul><h3 data-v-57f065f9>5.2 Right to Request Amendment</h3><p data-v-57f065f9> Students may request amendment of education records they believe are: </p><ul data-v-57f065f9><li data-v-57f065f9>Inaccurate</li><li data-v-57f065f9>Misleading</li><li data-v-57f065f9>In violation of privacy rights</li></ul><h3 data-v-57f065f9>5.3 Right to Control Disclosures</h3><p data-v-57f065f9> Students have the right to: </p><ul data-v-57f065f9><li data-v-57f065f9>Consent to disclosures of personally identifiable information</li><li data-v-57f065f9>Prevent disclosure of directory information (with proper opt-out)</li><li data-v-57f065f9>Receive notice of disclosures to certain parties</li></ul><h3 data-v-57f065f9>5.4 Right to File Complaints</h3><p data-v-57f065f9> Students may file complaints with the Department of Education if they believe FERPA rights have been violated. </p><h2 data-v-57f065f9>6. Our Technical Safeguards</h2><h3 data-v-57f065f9>6.1 Data Security Measures</h3><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>Encryption:</strong> All student data encrypted in transit and at rest</li><li data-v-57f065f9><strong data-v-57f065f9>Access Controls:</strong> Role-based access with multi-factor authentication</li><li data-v-57f065f9><strong data-v-57f065f9>Audit Logging:</strong> Comprehensive logging of all data access</li><li data-v-57f065f9><strong data-v-57f065f9>Regular Security Assessments:</strong> Vulnerability testing and security reviews</li><li data-v-57f065f9><strong data-v-57f065f9>Secure Infrastructure:</strong> SOC 2 compliant hosting environment</li></ul><h3 data-v-57f065f9>6.2 Administrative Safeguards</h3><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>Staff Training:</strong> Regular FERPA training for all personnel</li><li data-v-57f065f9><strong data-v-57f065f9>Background Checks:</strong> Screening for employees with data access</li><li data-v-57f065f9><strong data-v-57f065f9>Need-to-Know Access:</strong> Limiting access to those with legitimate need</li><li data-v-57f065f9><strong data-v-57f065f9>Incident Response:</strong> Procedures for handling data breaches</li></ul><h2 data-v-57f065f9>7. Data Retention and Destruction</h2><h3 data-v-57f065f9>7.1 Retention Policies</h3><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>Active Course Data:</strong> Duration of course plus institutional requirements</li><li data-v-57f065f9><strong data-v-57f065f9>Historical Records:</strong> As specified by institutional retention policies</li><li data-v-57f065f9><strong data-v-57f065f9>Analytics Data:</strong> Aggregated/de-identified data for service improvement</li><li data-v-57f065f9><strong data-v-57f065f9>Audit Logs:</strong> Maintained per institutional and legal requirements</li></ul><h3 data-v-57f065f9>7.2 Secure Destruction</h3><ul data-v-57f065f9><li data-v-57f065f9>Secure deletion methods that render data unrecoverable</li><li data-v-57f065f9>Documented destruction processes</li><li data-v-57f065f9>Verification of complete data removal</li><li data-v-57f065f9>Compliance with institutional data destruction requirements</li></ul><h2 data-v-57f065f9>8. Institutional Agreements</h2><h3 data-v-57f065f9>8.1 Data Processing Agreements</h3><p data-v-57f065f9> Our agreements with educational institutions include: </p><ul data-v-57f065f9><li data-v-57f065f9>Specification of FERPA compliance responsibilities</li><li data-v-57f065f9>Data use restrictions and permitted purposes</li><li data-v-57f065f9>Security requirements and breach notification procedures</li><li data-v-57f065f9>Data retention and destruction requirements</li><li data-v-57f065f9>Audit rights and compliance monitoring</li></ul><h3 data-v-57f065f9>8.2 Service Provider Requirements</h3><ul data-v-57f065f9><li data-v-57f065f9>Use data only for authorized educational purposes</li><li data-v-57f065f9>Not disclose information to unauthorized parties</li><li data-v-57f065f9>Maintain reasonable security measures</li><li data-v-57f065f9>Return or destroy data upon contract termination</li><li data-v-57f065f9>Allow institutional oversight and auditing</li></ul><h2 data-v-57f065f9>9. Directory Information</h2><h3 data-v-57f065f9>9.1 Standard Directory Information</h3><p data-v-57f065f9> We may display directory information as designated by the institution: </p><ul data-v-57f065f9><li data-v-57f065f9>Student name</li><li data-v-57f065f9>Email address (if designated)</li><li data-v-57f065f9>Course enrollment (if designated)</li><li data-v-57f065f9>Participation in activities</li></ul><h3 data-v-57f065f9>9.2 Opt-Out Procedures</h3><ul data-v-57f065f9><li data-v-57f065f9>Respect institutional opt-out procedures</li><li data-v-57f065f9>Implement directory information restrictions</li><li data-v-57f065f9>Provide mechanisms for students to control visibility</li></ul><h2 data-v-57f065f9>10. Breach Response Procedures</h2><h3 data-v-57f065f9>10.1 Incident Identification</h3><ul data-v-57f065f9><li data-v-57f065f9>Automated monitoring for security incidents</li><li data-v-57f065f9>Staff reporting procedures</li><li data-v-57f065f9>Student and institutional reporting mechanisms</li></ul><h3 data-v-57f065f9>10.2 Response Actions</h3><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>Immediate:</strong> Contain the incident and prevent further exposure</li><li data-v-57f065f9><strong data-v-57f065f9>Assessment:</strong> Determine scope and impact within 24 hours</li><li data-v-57f065f9><strong data-v-57f065f9>Notification:</strong> Notify affected institutions immediately</li><li data-v-57f065f9><strong data-v-57f065f9>Investigation:</strong> Conduct thorough forensic analysis</li><li data-v-57f065f9><strong data-v-57f065f9>Remediation:</strong> Implement corrective measures</li><li data-v-57f065f9><strong data-v-57f065f9>Documentation:</strong> Maintain complete incident records</li></ul><h2 data-v-57f065f9>11. Audit and Compliance Monitoring</h2><h3 data-v-57f065f9>11.1 Internal Audits</h3><ul data-v-57f065f9><li data-v-57f065f9>Regular FERPA compliance assessments</li><li data-v-57f065f9>Access control reviews</li><li data-v-57f065f9>Data handling procedure evaluations</li><li data-v-57f065f9>Staff compliance training verification</li></ul><h3 data-v-57f065f9>11.2 External Audits</h3><ul data-v-57f065f9><li data-v-57f065f9>Third-party security assessments</li><li data-v-57f065f9>Institutional audit participation</li><li data-v-57f065f9>Compliance certification maintenance</li><li data-v-57f065f9>Documentation of audit findings and remediation</li></ul><h2 data-v-57f065f9>12. Record Keeping Requirements</h2><h3 data-v-57f065f9>12.1 Disclosure Records</h3><p data-v-57f065f9> We maintain records of all disclosures including: </p><ul data-v-57f065f9><li data-v-57f065f9>Parties who have requested or obtained access</li><li data-v-57f065f9>Legitimate interests of requesting parties</li><li data-v-57f065f9>Dates of access</li><li data-v-57f065f9>Records accessed</li></ul><h3 data-v-57f065f9>12.2 Access Logs</h3><ul data-v-57f065f9><li data-v-57f065f9>Comprehensive audit trails of all system access</li><li data-v-57f065f9>User authentication and authorization records</li><li data-v-57f065f9>Data modification and deletion logs</li><li data-v-57f065f9>Regular review and analysis of access patterns</li></ul><h2 data-v-57f065f9>13. Staff Training and Awareness</h2><h3 data-v-57f065f9>13.1 Initial Training</h3><ul data-v-57f065f9><li data-v-57f065f9>Comprehensive FERPA training for all new employees</li><li data-v-57f065f9>Role-specific privacy and security training</li><li data-v-57f065f9>Certification of training completion</li></ul><h3 data-v-57f065f9>13.2 Ongoing Education</h3><ul data-v-57f065f9><li data-v-57f065f9>Annual FERPA compliance refresher training</li><li data-v-57f065f9>Updates on law and regulation changes</li><li data-v-57f065f9>Best practice sharing and case studies</li><li data-v-57f065f9>Incident response training and drills</li></ul><h2 data-v-57f065f9>14. Institutional Support</h2><p data-v-57f065f9> We provide support to help educational institutions maintain FERPA compliance: </p><ul data-v-57f065f9><li data-v-57f065f9><strong data-v-57f065f9>Documentation:</strong> Comprehensive privacy and security documentation</li><li data-v-57f065f9><strong data-v-57f065f9>Training:</strong> FERPA compliance guidance for institutional users</li><li data-v-57f065f9><strong data-v-57f065f9>Auditing:</strong> Support for institutional FERPA audits</li><li data-v-57f065f9><strong data-v-57f065f9>Incident Response:</strong> Rapid response to privacy incidents</li><li data-v-57f065f9><strong data-v-57f065f9>Consultation:</strong> Ongoing privacy compliance consultation</li></ul><h2 data-v-57f065f9>15. Contact Information</h2><p data-v-57f065f9> For FERPA compliance questions or to report privacy concerns: </p><div class="bg-coral/20 border-l-4 border-coral p-6 rounded-r-lg mt-6" data-v-57f065f9><p data-v-57f065f9><strong data-v-57f065f9>FERPA Compliance Officer</strong></p><p data-v-57f065f9>Email: <a href="mailto:ferpa@classsemble.com" class="text-coral hover:underline" data-v-57f065f9>ferpa@classsemble.com</a></p><p data-v-57f065f9>Phone: +1 (555) 123-4567</p><p data-v-57f065f9>Address: 123 Education Street, San Francisco, CA 94102</p></div><h3 data-v-57f065f9>15.1 Department of Education</h3><p data-v-57f065f9> To file a FERPA complaint with the federal government: </p><div class="bg-gray-50 p-4 rounded-lg" data-v-57f065f9><p data-v-57f065f9><strong data-v-57f065f9>Family Policy Compliance Office</strong><br data-v-57f065f9> U.S. Department of Education<br data-v-57f065f9> 400 Maryland Avenue, SW<br data-v-57f065f9> Washington, DC 20202-8520</p><p data-v-57f065f9>Website: <a href="https://www2.ed.gov/policy/gen/guid/fpco/" class="text-coral hover:underline" data-v-57f065f9>www.ed.gov/policy/gen/guid/fpco/</a></p></div><p class="mt-8 p-4 bg-blue-50 rounded-lg" data-v-57f065f9><strong data-v-57f065f9>Commitment:</strong> Classsemble is committed to ongoing FERPA compliance and will promptly address any privacy concerns raised by students or educational institutions. </p></div></section>',2)),t(e)])}}}),A=c(u,[["__scopeId","data-v-57f065f9"]]);export{A as default};
